"""Advisory, generation-scoped flow control. Never acknowledges transport frames."""
import asyncio
import math


async def live_call(method, value):
    worker = asyncio.create_task(asyncio.to_thread(method, value))
    try:
        return await asyncio.shield(worker)
    except asyncio.CancelledError:
        await asyncio.gather(worker, return_exceptions=True)
        raise


class FrameFeedback:
    def __init__(self, session, display, owner, fps, adjustable, mode=None):
        self.session, self.display, self.owner = session, display, owner
        self.base = self.requested = float(fps)
        self.capable = adjustable
        self.mode = self.effective_mode(mode if mode is not None else ('true' if adjustable else 'observe'))
        self.adjustable = self.mode == 'true'
        self.generation = 0
        self.changed = -math.inf
        self.sample = None
        self.last = -math.inf
        self.token = None
        self.since = self.pressure = None

    def effective_mode(self, mode):
        if mode == 'true':
            return 'true' if self.capable else 'observe'
        return 'observe' if mode == 'observe' else 'false'

    def status(self):
        return f"VIDEO_QOE_MODE,{self.display},{self.token},{self.mode},{int(self.capable)}"

    def announce(self):
        offer = self.offer()
        return [self.status(), offer] if self.mode != 'false' else [self.status()]

    async def switch(self, mode, module):
        if mode == self.mode:
            return [self.status()]
        if self.requested != self.base:
            await live_call(module.update_framerate, self.base)
            self.requested = self.base
        self.mode = self.effective_mode(mode)
        self.adjustable = self.mode == 'true'
        return self.announce()

    def offer(self):
        self.generation += 1
        self.token = f"{self.session}.{self.generation}"
        self.sample = None
        self.last = -math.inf
        self.pressure = None
        self.since = None
        self.totals = [0, 0, 0]
        return f"VIDEO_QOE,{self.display},{self.token}"

    def receive(self, message, owner, now, congested):
        if self.mode == 'false' or owner is not self.owner or len(message) > 192 or now - self.last < 0.15:
            return False
        parts = message.split(',')
        if len(parts) != 14 or parts[:3] != ['CLIENT_QOE', self.display, self.token]:
            return False
        try:
            values = [int(field) for field in parts[3:]]
        except ValueError:
            return False
        rx, decoded, drawn, decode_lag, draw_lag, queue, draw_ms, input_ms, count, arrivals, outputs = values
        if (not 0 <= rx <= 65535 or not all(-1 <= frame <= 65535 for frame in (decoded, drawn))
                or not all(0 <= value <= 255 for value in (decode_lag, draw_lag, count, arrivals, outputs))
                or not -1 <= queue <= 255 or not all(-1 <= value <= 60000 for value in (draw_ms, input_ms))):
            return False
        pressure = bool(congested or max(decode_lag, draw_lag, queue) >= max(3, self.requested * 0.15))
        if now - self.last > 1 or pressure != self.pressure:
            self.since = now
        self.last, self.pressure = now, pressure
        self.sample = dict(zip(('received_id', 'decoded_id', 'drawn_id', 'decode_lag', 'draw_lag',
                                'decode_queue', 'receive_to_draw_ms', 'input_to_next_draw_ms', 'draw_samples'), values[:9]))
        self.totals = [total + delta for total, delta in zip(self.totals, (arrivals, outputs, count))]
        self.sample.update(generation=self.generation, received_total=self.totals[0],
                           decoded_total=self.totals[1], drawn_total=self.totals[2])
        return True

    def target(self, now, eligible):
        if not self.adjustable:
            return None
        if not eligible or now - self.last > 2:
            target = self.base
        elif self.since is None or now - self.last > 1 or now - self.changed < 2:
            return None
        elif self.pressure and self.last - self.since >= 0.75:
            target = max(min(self.base, max(6, math.ceil(self.base / 2))), math.floor(self.requested * 0.8))
        elif not self.pressure and self.last - self.since >= 3:
            target = min(self.base, self.requested + max(1, math.ceil(self.base / 8)))
        else:
            return None
        return target if target != self.requested else None
